          "qt": "<span class=\"qt-context\"><span class=\"series-label\">連問 2/3</span>85 歳の男性。発熱と呼吸困難を主訴に家族とともに来院した。<br/>現病歴：1 年前から息切れのため自宅の階段を昇ることが困難となり、食事や飲水の際のむせが出現した。食事量も<br/>低下し、半年間で体重が5kg 減少した。1 週間前から咳嗽と喀痰が多くなり、2 日前から38℃の発熱と呼吸困難が<br/>みられるようになったため家族に伴われて受診し、入院した。<br/>既往歴：15 年前から高血圧症に対してアンジオテンシン変換酵素〈ACE〉阻害薬を内服している。5 年前から物忘<br/>れが目立つようになり、2 年前にAlzheimer 型認知症と診断された。<br/>生活歴：65 歳まで会社員。現在は娘の家族と同居。喫煙は65 歳まで20 本/ 日を45 年間。飲酒歴はない。自宅で猫<br/>を飼育している。<br/>家族歴：両親とも脳梗塞で死亡。<br/>現　症：意識は清明。身長160cm、体重43kg。体温38.0℃。脈拍120/ 分、整。血圧122/78mmHg。呼吸数28/ 分。<br/>眼瞼結膜に異常を認めない。口腔内の衛生状態は不良である。心音に異常を認めない。呼吸音は両側でwheezes を、<br/>右背側でcoarse crackles を聴取する。腹部は平坦、軟で、肝・脾を触知しない。浮腫を認めない。<br/>検査所見：血液所見：赤血球412 万、Hb 13.1g/dL、Ht 40％、白血球9,800（好中球82％、好酸球2％、好塩基球<br/>0％、単球7％、リンパ球9％）、血小板34 万。血液生化学所見：総蛋白5.8g/dL、アルブミン2.9g/dL、総ビリル<br/>ビン1.1mg/dL、AST 14U/L、ALT 10U/L、LD 230U/L（基準120 ～245）、ALP 64U/L（基準38 ～113）、尿<br/>素窒素28mg/dL、クレアチニン1.5mg/dL、尿酸6.0mg/dL、血糖135mg/dL、Na 139mEq/L、K 4.7mEq/L、Cl<br/>106mEq/L。CRP 5.1mg/dL。動脈血ガス分析（鼻カニューラ2L/ 分酸素投与下）：pH 7.33、PaCO2 58Torr、PaO2<br/>72Torr、HCO3<br/>－ 30mEq/L。新型コロナウイルス〈SARS-CoV-2〉PCR 検査は陰性であった。</span><br/><strong>呼吸状態の急性増悪に対し、抗菌薬とともに用いる薬剤として適切なのはどれか。</strong>",
